const convs={"creator":"6abda62d-8198-83ed-aaa2-40b16f96a8a0","media":"6abda64b-aac4-83eb-adee-dc7143ca5d2b","growth":"6abda63c-98d8-83ed-b365-d423b7563c4b","bridge":"6abda61c-a440-83ed-9482-1d0fc7923e03"};
const tabs=await (await fetch("http://127.0.0.1:17410/json/list")).json();
const out={};
for(const [name,conv] of Object.entries(convs)){
  const matches=tabs.filter(t=>t.type==="page" && (t.url||"").includes(conv));
  out[name]={conversation_id:conv,matches:[]};
  for(const tab of matches){
    try{
      const ws=new WebSocket(tab.webSocketDebuggerUrl);
      await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j});
      let seq=1,p=new Map();
      ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&p.has(m.id)){p.get(m.id)(m);p.delete(m.id)}};
      const call=(method,params={})=>new Promise((r,j)=>{const k=seq++;p.set(k,m=>m.error?j(new Error(JSON.stringify(m.error))):r(m.result));ws.send(JSON.stringify({id:k,method,params}))});
      const expr=`JSON.stringify((()=> {
        const composer=document.querySelector('#prompt-textarea')||[...document.querySelectorAll('[contenteditable="true"],textarea')].find(e=>{const r=e.getBoundingClientRect();return r.width>0&&r.height>0});
        const composerText=composer ? ((('value' in composer)?composer.value:(composer.innerText||composer.textContent||''))||'') : '';
        const buttons=[...document.querySelectorAll('button')].filter(b=>{const r=b.getBoundingClientRect();return r.width>0&&r.height>0});
        const generating=buttons.some(b=>{
          const x=((b.getAttribute('data-testid')||'')+' '+(b.getAttribute('aria-label')||'')+' '+(b.innerText||'')).toLowerCase();
          return x.includes('stop')||x.includes('останов');
        });
        const msgs=[...document.querySelectorAll('[data-message-author-role]')].slice(-8).map(m=>({
          role:m.getAttribute('data-message-author-role'),
          text:(m.innerText||m.textContent||'').trim().replace(/\\s+/g,' ').slice(0,900)
        }));
        return {
          href:location.href,
          title:document.title,
          composer_found:!!composer,
          composer_text:composerText,
          composer_length:composerText.length,
          generating,
          last_messages:msgs
        };
      })())`;
      const rr=await call("Runtime.evaluate",{expression:expr,returnByValue:true});
      out[name].matches.push({tab_id:tab.id,tab_url:tab.url,state:JSON.parse(rr.result.value)});
      ws.close();
    }catch(e){
      out[name].matches.push({tab_id:tab.id,tab_url:tab.url,error:String(e)});
    }
  }
}
process.stdout.write(JSON.stringify(out));

